import type { HTMLAttributes } from 'react'

import { cx } from '~/lib/cx'
import styles from './card.module.scss'

export interface CardProps extends HTMLAttributes<HTMLDivElement> {
  /** Remove elevation for a quieter, bordered surface. */
  flat?: boolean
  /** Adds hover lift — use when the whole card is a link. */
  interactive?: boolean
  /** Apply the shared inner padding (for simple cards without sections). */
  padded?: boolean
}

export function Card({
  flat = false,
  interactive = false,
  padded = false,
  className,
  ...props
}: CardProps) {
  return (
    <div
      className={cx(
        styles.root,
        flat && styles.flat,
        interactive && styles.interactive,
        padded && styles.padded,
        className,
      )}
      {...props}
    />
  )
}

export function CardHeader({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return <div className={cx(styles.header, className)} {...props} />
}

export function CardTitle({
  className,
  ...props
}: HTMLAttributes<HTMLHeadingElement>) {
  return <h3 className={cx(styles.title, className)} {...props} />
}

export function CardDescription({
  className,
  ...props
}: HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cx(styles.description, className)} {...props} />
}

export function CardContent({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return <div className={cx(styles.content, className)} {...props} />
}

export function CardFooter({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return <div className={cx(styles.footer, className)} {...props} />
}

@use 'styles' as vz;

.root {
  --card-pad: #{vz.space(5)};
  --card-radius: #{vz.radius('2xl')};

  display: flex;
  flex-direction: column;
  border: 1px solid vz.color('border');
  border-radius: var(--card-radius);
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(1);
  transition:
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out'),
    transform vz.duration('base') vz.ease('out');
}

.flat {
  box-shadow: none;
}

.interactive {
  @include vz.hover {
    border-color: vz.color('foreground', 0.14);
    box-shadow: vz.elevation(2);
    transform: translateY(-1px);
  }

  @include vz.motion-reduce {
    @include vz.hover {
      transform: none;
    }
  }
}

.padded {
  padding: var(--card-pad);
}

.header {
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
  padding: var(--card-pad) var(--card-pad) 0;
}

.padded .header {
  padding: 0;
}

.title {
  margin: 0;
  font-size: vz.font-size('lg');
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.5;
}

.content {
  padding: var(--card-pad);
}

.padded .content {
  padding: 0;
}

.header + .content {
  padding-top: vz.space(4);
}

.padded .header + .content {
  padding-top: vz.space(4);
}

.footer {
  display: flex;
  align-items: center;
  gap: vz.space(2);
  padding: 0 var(--card-pad) var(--card-pad);
}

.padded .footer {
  padding: vz.space(4) 0 0;
  border-top: 1px solid vz.color('border');
  margin-top: vz.space(4);
}

@include vz.up('md') {
  .root {
    --card-pad: #{vz.space(6)};
  }
}
